import React, { useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Divider,
  Grid,
  Stack,
  Autocomplete,
  MenuItem,
  TextField,
  Typography,
} from '@mui/material';
import EditOutlined from '@mui/icons-material/EditOutlined';
import MyLocationOutlined from '@mui/icons-material/MyLocationOutlined';
import { Link as RouterLink } from 'react-router-dom';
import ApiService from '../services/api';
import GpsGeotaggedCapture from './compliance/GpsGeotaggedCapture';
import SectorSetupCard from './shared/SectorSetupCard';
import { getCurrentGpsCoordinates } from '../utils/geolocation';
import {
  coerceSectorFormPreset,
  energyNeedsDiscom,
  resolveSectorFormPreset,
  suggestEmptyFacilityFields,
  type SectorFormPreset,
} from '../constants/msmeSectorFormOptions';

export type MsmeReportingFacilityProfile = {
  businessDomain?: string;
  industry?: string;
  business?: {
    manufacturingUnits?: number;
    primaryProducts?: string;
    manufacturingWorkflow?: {
      units?: Array<{
        unitId?: string;
        name?: string;
        location?: string;
        products?: string[] | string;
        processes?: unknown[];
      }>;
    };
  };
  manufacturingProfile?: {
    industrySector?: string;
    keyProducts?: string[];
    installationLatitude?: number;
    installationLongitude?: number;
    locationCity?: string;
    locationState?: string;
    primaryEnergySource?: string;
    electricityDiscomId?: string;
    mainFuelsUsed?: string[];
    productionCapacityPerMonth?: number;
    productionCapacityUnit?: string;
  };
};

export type FacilityEditorSection = 'all' | 'site' | 'energy';

type MsmeReportingFacilityEditorProps = {
  profile: MsmeReportingFacilityProfile | null;
  onSaved?: () => void | Promise<void>;
  /** Site details live on Manufacturing units. Energy details live on Energy and meters. */
  section?: FacilityEditorSection;
};

type ElectricityDiscomOption = {
  id: string;
  name: string;
  energyChargeInrPerUnit?: number;
  source?: string;
  yearMonth?: string | null;
};

const FALLBACK_DISCOMS: ElectricityDiscomOption[] = [
  { id: 'msedcl', name: 'Maharashtra State Electricity Distribution Co. Ltd. (MSEDCL)' },
  { id: 'bescom', name: 'Bangalore Electricity Supply Company Ltd. (BESCOM)' },
  { id: 'mescom', name: 'Mangalore Electricity Supply Company Ltd. (MESCOM)' },
  { id: 'hescom', name: 'Hubli Electricity Supply Company Ltd. (HESCOM)' },
  { id: 'gescom', name: 'Gulbarga Electricity Supply Company Ltd. (GESCOM)' },
  { id: 'cesc_mysore', name: 'Chamundeshwari Electricity Supply Corporation Ltd. (CESC Mysuru)' },
];

const splitProducts = (value: string) =>
  value
    .split(/[,;|]/g)
    .map((item) => item.trim())
    .filter(Boolean);

const MsmeReportingFacilityEditor: React.FC<MsmeReportingFacilityEditorProps> = ({
  profile,
  onSaved,
  section = 'all',
}) => {
  const [editing, setEditing] = useState(section !== 'all');
  const [saving, setSaving] = useState(false);
  const [gpsLoading, setGpsLoading] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [usedSectorSuggestions, setUsedSectorSuggestions] = useState(false);
  const [setupBusy, setSetupBusy] = useState(false);
  const [setupClarification, setSetupClarification] = useState<string | null>(null);
  const [discoms, setDiscoms] = useState<ElectricityDiscomOption[]>(FALLBACK_DISCOMS);
  const [draft, setDraft] = useState({
    unitName: '',
    unitLocation: '',
    products: '',
    manufacturingUnits: '1',
    installationLatitude: '',
    installationLongitude: '',
    primaryEnergySource: '',
    electricityDiscomId: '',
    mainFuelsUsed: '',
    productionCapacityPerMonth: '',
    productionCapacityUnit: 'kg',
  });

  const seedFromProfile = useMemo(() => {
    const units = profile?.business?.manufacturingWorkflow?.units;
    const primaryUnit = Array.isArray(units) && units.length > 0 ? units[0] : null;
    const manufacturingProfile = profile?.manufacturingProfile;
    const unitProducts = primaryUnit?.products;
    const productsFromUnit = Array.isArray(unitProducts)
      ? unitProducts.join(', ')
      : String(unitProducts || '');
    const keyProducts = manufacturingProfile?.keyProducts;
    const productsFromProfile = Array.isArray(keyProducts)
      ? keyProducts.join(', ')
      : '';
    const mainFuelsUsed = manufacturingProfile?.mainFuelsUsed;
    const primaryProducts = String(profile?.business?.primaryProducts || '').trim();

    return {
      unitName: String(primaryUnit?.name || '').trim(),
      unitLocation: String(
        primaryUnit?.location
        || manufacturingProfile?.locationCity
        || ''
      ).trim(),
      products: productsFromUnit || productsFromProfile || primaryProducts,
      manufacturingUnits: String(
        profile?.business?.manufacturingUnits
        || (Array.isArray(units) && units.length > 0 ? units.length : 1)
      ),
      installationLatitude:
        manufacturingProfile?.installationLatitude != null
          ? String(manufacturingProfile.installationLatitude)
          : '',
      installationLongitude:
        manufacturingProfile?.installationLongitude != null
          ? String(manufacturingProfile.installationLongitude)
          : '',
      primaryEnergySource: String(manufacturingProfile?.primaryEnergySource || ''),
      electricityDiscomId: String(manufacturingProfile?.electricityDiscomId || ''),
      mainFuelsUsed: Array.isArray(mainFuelsUsed)
        ? mainFuelsUsed.join(', ')
        : '',
      productionCapacityPerMonth:
        manufacturingProfile?.productionCapacityPerMonth != null
          ? String(manufacturingProfile.productionCapacityPerMonth)
          : '',
      productionCapacityUnit: String(manufacturingProfile?.productionCapacityUnit || 'kg'),
    };
  }, [profile]);

  useEffect(() => {
    setDraft(seedFromProfile);
  }, [seedFromProfile]);

  useEffect(() => {
    let active = true;
    ApiService.getElectricityDiscoms()
      .then((response) => {
        const rows = response?.data?.discoms;
        if (!active || !Array.isArray(rows) || rows.length === 0) return;
        setDiscoms(rows.map((row: ElectricityDiscomOption) => ({
          id: row.id,
          name: row.name,
          energyChargeInrPerUnit: row.energyChargeInrPerUnit,
          source: row.source,
          yearMonth: row.yearMonth,
        })));
      })
      .catch(() => {
        if (active) setDiscoms(FALLBACK_DISCOMS);
      });
    return () => {
      active = false;
    };
  }, []);

  const sectorPreset = useMemo(
    () => resolveSectorFormPreset({
      businessDomain: profile?.businessDomain,
      industry: profile?.industry,
      industrySector: profile?.manufacturingProfile?.industrySector,
    }),
    [profile]
  );

  const missingRequired = useMemo(() => {
    const gaps: string[] = [];
    if (section === 'all') {
      if (!draft.unitName.trim()) gaps.push('Manufacturing unit name');
      if (!draft.products.trim()) gaps.push('Products manufactured');
    }
    if (section !== 'site') {
      if (!draft.primaryEnergySource.trim()) gaps.push('Primary energy source');
      if (!draft.mainFuelsUsed.trim()) gaps.push('Main fuels used');
      if (energyNeedsDiscom(draft.primaryEnergySource) && !draft.electricityDiscomId.trim()) {
        gaps.push('Electricity supplier');
      }
    }
    return gaps;
  }, [draft, section]);

  const applyFacilityPreset = (preset: SectorFormPreset) => {
    const next = suggestEmptyFacilityFields(preset, draft);
    const changed = next.unitName !== draft.unitName
      || next.products !== draft.products
      || next.primaryEnergySource !== draft.primaryEnergySource
      || next.mainFuelsUsed !== draft.mainFuelsUsed
      || next.productionCapacityUnit !== draft.productionCapacityUnit;
    setDraft(next);
    setUsedSectorSuggestions(changed);
    setEditing(true);
  };

  const startEditing = () => {
    applyFacilityPreset(sectorPreset);
  };

  const useSectorSetup = async () => {
    if (setupBusy) return;
    setSetupBusy(true);
    try {
      const response = await ApiService.previewOperationsTemplate();
      const plant = (response?.data?.plantSetup || null) as Partial<SectorFormPreset> | null;
      const requests = response?.data?.userClarificationRequests;
      const prompt = Array.isArray(requests) && requests[0]?.prompt ? String(requests[0].prompt) : null;
      setSetupClarification(prompt);
      applyFacilityPreset(coerceSectorFormPreset(plant, sectorPreset));
    } catch {
      setSetupClarification(null);
      applyFacilityPreset(sectorPreset);
    } finally {
      setSetupBusy(false);
    }
  };

  const captureCurrentGps = async () => {
    setGpsLoading(true);
    setError(null);
    try {
      const result = await getCurrentGpsCoordinates({ enableHighAccuracy: true, timeoutMs: 20000 });
      if (!result.ok) {
        throw new Error(result.error || 'Unable to read GPS coordinates.');
      }
      setDraft((current) => ({
        ...current,
        installationLatitude: result.coords.latitude.toFixed(6),
        installationLongitude: result.coords.longitude.toFixed(6),
      }));
      setFeedback('GPS coordinates filled from your device. Save facility details to keep them.');
      setEditing(true);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'GPS capture failed.';
      // Permission/unavailable must not block profile editing — GPS stays optional.
      setError(null);
      setFeedback(
        /permission denied|unavailable|timed out|not support/i.test(message)
          ? 'Location not available. GPS is optional — enter coordinates manually or skip for now.'
          : message
      );
    } finally {
      setGpsLoading(false);
    }
  };

  const saveFacility = async () => {
    if (missingRequired.length > 0) {
      setError(`Required before saving: ${missingRequired.join(', ')}.`);
      return;
    }

    setSaving(true);
    setError(null);
    setFeedback(null);
    try {
      const products = splitProducts(draft.products);
      const fuels = splitProducts(draft.mainFuelsUsed);
      const lat = draft.installationLatitude.trim() === ''
        ? undefined
        : Number(draft.installationLatitude);
      const lng = draft.installationLongitude.trim() === ''
        ? undefined
        : Number(draft.installationLongitude);
      if (
        (draft.installationLatitude.trim() && !Number.isFinite(lat))
        || (draft.installationLongitude.trim() && !Number.isFinite(lng))
      ) {
        throw new Error('GPS latitude/longitude must be valid numbers.');
      }

      const workflowUnits = profile?.business?.manufacturingWorkflow?.units;
      const existingUnits = Array.isArray(workflowUnits) ? workflowUnits : [];
      const primaryUnit = {
        ...(existingUnits[0] || {}),
        unitId: String(existingUnits[0]?.unitId || 'unit-1'),
        name: draft.unitName.trim(),
        location: draft.unitLocation.trim(),
        products,
        processes: Array.isArray(existingUnits[0]?.processes) ? existingUnits[0].processes : [],
      };
      const nextUnits = existingUnits.length > 0
        ? [primaryUnit, ...existingUnits.slice(1)]
        : [primaryUnit];

      const unitCount = Math.max(
        1,
        Number.parseInt(draft.manufacturingUnits, 10) || nextUnits.length || 1
      );

      await ApiService.updateMSMEProfile({
        business: {
          manufacturingUnits: unitCount,
          primaryProducts: products.join(', '),
          manufacturingWorkflow: {
            ...(profile?.business?.manufacturingWorkflow || {}),
            units: nextUnits,
          },
        },
        manufacturingProfile: {
          keyProducts: products,
          locationCity: draft.unitLocation.trim() || undefined,
          installationLatitude: lat,
          installationLongitude: lng,
          primaryEnergySource: draft.primaryEnergySource.trim() || undefined,
          electricityDiscomId: draft.electricityDiscomId.trim() || undefined,
          mainFuelsUsed: fuels,
          productionCapacityPerMonth: draft.productionCapacityPerMonth.trim()
            ? Number(draft.productionCapacityPerMonth)
            : undefined,
          productionCapacityUnit: draft.productionCapacityUnit.trim() || undefined,
        },
      });

      setFeedback('Reporting facility details saved to your company profile.');
      setEditing(false);
      await onSaved?.();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unable to save facility details.');
    } finally {
      setSaving(false);
    }
  };

  const renderReadonly = (label: string, value: string) => (
    <Box>
      <Typography variant="body2" color="text.secondary">{label}</Typography>
      <Typography variant="body1">{value || 'Not provided'}</Typography>
    </Box>
  );

  return (
    <Card variant="outlined">
      <CardContent>
        <Stack direction="row" justifyContent="space-between" alignItems="flex-start" sx={{ mb: 2 }} gap={1}>
          <Box>
            <Typography variant="h6" sx={{ fontWeight: 700 }}>
              {section === 'energy' ? 'Energy and fuels' : section === 'site' ? 'Site details' : 'Facility & products for reporting'}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 680 }}>
              {section === 'energy'
                ? 'Required. Primary energy source and fuels. The electricity supplier is required when the plant uses grid electricity. Monthly meters are on this page.'
                : section === 'site'
                  ? 'Number of units, production capacity, and GPS. Unit name, city, and products are in the manufacturing unit list on this page.'
                  : 'Use the sector setup, then save. Unit, products, energy, and fuel are required. GPS is optional.'}
            </Typography>
          </Box>
          {!editing ? (
            <Button size="small" variant="outlined" startIcon={<EditOutlined />} onClick={startEditing}>
              Edit
            </Button>
          ) : null}
        </Stack>

        {section === 'all' ? (
        <SectorSetupCard
          preset={sectorPreset}
          onUse={useSectorSetup}
          disabled={setupBusy}
          used={usedSectorSuggestions}
        />
        ) : null}

        {setupClarification ? (
          <Alert severity="warning" sx={{ mb: 2 }}>{setupClarification}</Alert>
        ) : null}

        {missingRequired.length > 0 ? (
          <Alert severity="warning" sx={{ mb: 2 }}>
            Missing for report readiness: {missingRequired.join(', ')}.
          </Alert>
        ) : (
          <Alert severity="success" sx={{ mb: 2 }}>
            Core facility fields for reporting are complete. GPS coordinates and site photo remain optional —
            add them later when buyers or auditors need geotagged evidence.
          </Alert>
        )}

        {editing ? (
          <Alert severity="info" sx={{ mb: 2 }}>
            {usedSectorSuggestions
              ? 'Suggested lines are filled. Change any that do not match your plant, then save.'
              : 'Required fields are marked. You can type a value that is not in the list.'}
          </Alert>
        ) : null}

        {feedback ? <Alert severity="success" sx={{ mb: 2 }}>{feedback}</Alert> : null}
        {error ? <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert> : null}

        <Grid container spacing={2}>
          {section === 'all' ? (
          <>
          <Grid item xs={12} md={6}>
            {editing ? (
              <Autocomplete
                freeSolo
                options={sectorPreset.unitNames}
                value={draft.unitName}
                onInputChange={(_event, value, reason) => {
                  if (reason === 'reset') return;
                  setDraft((current) => ({ ...current, unitName: value }));
                }}
                renderInput={(params) => (
                  <TextField
                    {...params}
                    required
                    label="Manufacturing unit name"
                    helperText={`Suggested for ${sectorPreset.label}. You can type another name.`}
                  />
                )}
              />
            ) : renderReadonly('Manufacturing unit name', draft.unitName)}
          </Grid>
          <Grid item xs={12} md={6}>
            {editing ? (
              <TextField
                fullWidth
                label="Unit location / city"
                value={draft.unitLocation}
                onChange={(e) => setDraft((current) => ({ ...current, unitLocation: e.target.value }))}
              />
            ) : renderReadonly('Unit location / city', draft.unitLocation)}
          </Grid>
          <Grid item xs={12} md={8}>
            {editing ? (
              <Autocomplete
                multiple
                freeSolo
                options={sectorPreset.products}
                value={splitProducts(draft.products)}
                onChange={(_event, value) => setDraft((current) => ({
                  ...current,
                  products: value.map((item) => String(item).trim()).filter(Boolean).join(', '),
                }))}
                renderInput={(params) => (
                  <TextField
                    {...params}
                    required
                    label="Products manufactured"
                    helperText="Required. Pick the sector products or type your own, then press Enter."
                  />
                )}
              />
            ) : renderReadonly('Products manufactured', draft.products)}
          </Grid>
          </>
          ) : null}
          {section !== 'energy' ? (
          <>
          <Grid item xs={12} md={4}>
            {editing ? (
              <TextField
                fullWidth
                label="Number of units"
                type="number"
                value={draft.manufacturingUnits}
                onChange={(e) => setDraft((current) => ({ ...current, manufacturingUnits: e.target.value }))}
                inputProps={{ min: 1, max: 999 }}
              />
            ) : renderReadonly('Number of units', draft.manufacturingUnits)}
          </Grid>
          <Grid item xs={12} md={4}>
            {editing ? (
              <TextField
                fullWidth
                label="Facility GPS latitude (optional)"
                value={draft.installationLatitude}
                error={
                  draft.installationLatitude.trim() !== ''
                  && !Number.isFinite(Number(draft.installationLatitude))
                }
                onChange={(e) => setDraft((current) => ({ ...current, installationLatitude: e.target.value }))}
                helperText={
                  draft.installationLatitude.trim() !== ''
                  && !Number.isFinite(Number(draft.installationLatitude))
                    ? 'Enter a numeric latitude (or leave blank)'
                    : 'Optional during registration'
                }
              />
            ) : renderReadonly('Facility GPS latitude (optional)', draft.installationLatitude)}
          </Grid>
          <Grid item xs={12} md={4}>
            {editing ? (
              <TextField
                fullWidth
                label="Facility GPS longitude (optional)"
                value={draft.installationLongitude}
                error={
                  draft.installationLongitude.trim() !== ''
                  && !Number.isFinite(Number(draft.installationLongitude))
                }
                onChange={(e) => setDraft((current) => ({ ...current, installationLongitude: e.target.value }))}
                helperText={
                  draft.installationLongitude.trim() !== ''
                  && !Number.isFinite(Number(draft.installationLongitude))
                    ? 'Enter a numeric longitude (or leave blank)'
                    : 'Optional during registration'
                }
              />
            ) : renderReadonly('Facility GPS longitude (optional)', draft.installationLongitude)}
          </Grid>
          <Grid item xs={12} md={4}>
            <Stack spacing={1} sx={{ height: '100%', justifyContent: 'center' }}>
              <Button
                variant="outlined"
                startIcon={<MyLocationOutlined />}
                onClick={() => void captureCurrentGps()}
                disabled={gpsLoading}
              >
                {gpsLoading ? 'Reading GPS…' : 'Use current GPS'}
              </Button>
              <Button
                component={RouterLink}
                to="/compliance/geotagged-capture"
                size="small"
                variant="text"
              >
                Open full GPS capture page
              </Button>
            </Stack>
          </Grid>
          </>
          ) : null}
          {section !== 'site' ? (
          <>
          <Grid item xs={12} md={6}>
            {editing ? (
              <Autocomplete
                freeSolo
                options={sectorPreset.energySources}
                value={draft.primaryEnergySource}
                onInputChange={(_event, value, reason) => {
                  if (reason === 'reset') return;
                  setDraft((current) => ({ ...current, primaryEnergySource: value }));
                }}
                renderInput={(params) => (
                  <TextField
                    {...params}
                    required
                    label="Primary energy source"
                    helperText="Required. This tells carbon calculations which fuel family to use."
                  />
                )}
              />
            ) : renderReadonly('Primary energy source', draft.primaryEnergySource)}
          </Grid>
          <Grid item xs={12} md={6}>
            {editing ? (
              <TextField
                select
                fullWidth
                required={energyNeedsDiscom(draft.primaryEnergySource)}
                label="Electricity supplier"
                value={draft.electricityDiscomId}
                onChange={(e) => setDraft((current) => ({ ...current, electricityDiscomId: e.target.value }))}
                helperText={(() => {
                  const selected = discoms.find((row) => row.id === draft.electricityDiscomId);
                  if (!selected) {
                    return 'The industrial energy charge for this electricity supplier is stored each month and used when a bill has rupees but no kWh.';
                  }
                  const price = selected.energyChargeInrPerUnit != null
                    ? `₹${selected.energyChargeInrPerUnit}/kWh`
                    : 'cited industrial energy charge';
                  const month = selected.yearMonth ? ` Stored for ${selected.yearMonth}.` : '';
                  return `${price} from ${selected.source || 'the cited supplier tariff order'}.${month} Demand charges are not included.`;
                })()}
              >
                <MenuItem value="">Not set</MenuItem>
                {discoms.map((row) => (
                  <MenuItem key={row.id} value={row.id}>{row.name}</MenuItem>
                ))}
              </TextField>
            ) : renderReadonly(
              'Electricity supplier',
              discoms.find((row) => row.id === draft.electricityDiscomId)?.name || draft.electricityDiscomId
            )}
          </Grid>
          <Grid item xs={12} md={6}>
            {editing ? (
              <Autocomplete
                multiple
                freeSolo
                options={sectorPreset.fuels}
                value={splitProducts(draft.mainFuelsUsed)}
                onChange={(_event, value) => setDraft((current) => ({
                  ...current,
                  mainFuelsUsed: value.map((item) => String(item).trim()).filter(Boolean).join(', '),
                }))}
                renderInput={(params) => (
                  <TextField
                    {...params}
                    required
                    label="Main fuels used"
                    helperText="Required. At least one fuel. Pick the sector list or add another."
                  />
                )}
              />
            ) : renderReadonly('Main fuels used', draft.mainFuelsUsed)}
          </Grid>
          </>
          ) : null}
          {section !== 'energy' ? (
          <>
          <Grid item xs={12} md={6}>
            {editing ? (
              <TextField
                fullWidth
                label="Production capacity / month"
                type="number"
                value={draft.productionCapacityPerMonth}
                onChange={(e) => setDraft((current) => ({ ...current, productionCapacityPerMonth: e.target.value }))}
                helperText="Used for BRSR intensity disclosures"
              />
            ) : renderReadonly('Production capacity / month', draft.productionCapacityPerMonth)}
          </Grid>
          <Grid item xs={12} md={6}>
            {editing ? (
              <Autocomplete
                freeSolo
                options={sectorPreset.capacityUnits}
                value={draft.productionCapacityUnit}
                onInputChange={(_event, value, reason) => {
                  if (reason === 'reset') return;
                  setDraft((current) => ({ ...current, productionCapacityUnit: value }));
                }}
                renderInput={(params) => (
                  <TextField
                    {...params}
                    label="Capacity unit"
                    helperText="Suggested unit for this sector. Optional."
                  />
                )}
              />
            ) : renderReadonly('Capacity unit', draft.productionCapacityUnit)}
          </Grid>
          </>
          ) : null}
        </Grid>

        {editing ? (
          <Stack direction="row" spacing={1} sx={{ mt: 2 }}>
            <Button
              variant="contained"
              onClick={() => void saveFacility()}
              disabled={
                saving
                || missingRequired.length > 0
                || (
                  draft.installationLatitude.trim() !== ''
                  && !Number.isFinite(Number(draft.installationLatitude))
                )
                || (
                  draft.installationLongitude.trim() !== ''
                  && !Number.isFinite(Number(draft.installationLongitude))
                )
              }
            >
              {saving ? 'Saving…' : section === 'energy' ? 'Save energy details' : section === 'site' ? 'Save site details' : 'Save facility details'}
            </Button>
            <Button
              variant="text"
              onClick={() => {
                setEditing(false);
                setError(null);
                setDraft(seedFromProfile);
              }}
            >
              Cancel
            </Button>
          </Stack>
        ) : null}

        {section !== 'energy' ? <Divider sx={{ my: 3 }} /> : null}
        {section !== 'energy' ? (
        <>
        <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1 }} flexWrap="wrap" useFlexGap>
          <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
            GPS site photo
          </Typography>
          <Chip size="small" label="Optional" color="default" variant="outlined" />
        </Stack>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5, maxWidth: 720 }}>
          Optional during MSME registration. Capture a geotagged facility photo later when buyers need CBAM,
          ISO, or PAT site evidence. You can skip this and continue with bills and footprint.
        </Typography>
        <GpsGeotaggedCapture
          workflow="iso_site_evidence"
          optional
          autoRequestGps={false}
          onComplete={() => {
            void (async () => {
              const result = await getCurrentGpsCoordinates({
                enableHighAccuracy: true,
                timeoutMs: 20000,
              });
              if (result.ok && result.coords) {
                try {
                  await ApiService.updateMSMEProfile({
                    manufacturingProfile: {
                      installationLatitude: result.coords.latitude,
                      installationLongitude: result.coords.longitude,
                    },
                  });
                  setDraft((current) => ({
                    ...current,
                    installationLatitude: result.coords.latitude.toFixed(6),
                    installationLongitude: result.coords.longitude.toFixed(6),
                  }));
                  setFeedback('GPS site photo uploaded and facility coordinates saved to profile.');
                } catch (err) {
                  setError(err instanceof Error ? err.message : 'Photo uploaded but coordinates were not saved.');
                }
              }
              await onSaved?.();
            })();
          }}
        />
        </>
        ) : null}
      </CardContent>
    </Card>
  );
};

export default MsmeReportingFacilityEditor;
